const LEGACY_CITY_NAMES={'서울 성동구':'Seoul, Seongdong-gu','서울 마포구':'Seoul, Mapo-gu','서울 종로구':'Seoul, Jongno-gu','서울 강남구':'Seoul, Gangnam-gu','경기 성남시':'Seongnam','기타 지역':''};
function cleanCity(value){return String(value||'').trim().replace(/[\u0000-\u001f\u007f]/g,'').slice(0,80)}
function countryName(code,language=locale){return COUNTRIES[code]?pick(COUNTRIES[code],language):String(code||'')}
function normalizeLocation(value={}){if(typeof value==='string')value={region:value};const text=cleanCity(value.locationText||value.location?.text||'');if(text)return{countryCode:'',city:'',region:text,locationText:text};const legacy=String(value.region||'').trim(),candidate=String(value.countryCode||value.location?.countryCode||(Object.hasOwn(COUNTRIES,legacy)?legacy:'')).toUpperCase();let countryCode=Object.hasOwn(COUNTRIES,candidate)?candidate:'',city=cleanCity(value.city??value.location?.city??'');if(!countryCode&&Object.hasOwn(LOCATIONS,legacy)){countryCode='KR';if(!city)city=LEGACY_CITY_NAMES[legacy]||''}if(!countryCode&&!city&&legacy)city=cleanCity(legacy);return{countryCode,city,region:legacy||[city,countryCode?COUNTRIES[countryCode][0]:''].filter(Boolean).join(', '),locationText:''}}
function displayLocation(value,language=locale){const place=normalizeLocation(value);if(place.locationText)return place.locationText;if(!place.countryCode&&typeof value==='string')return LOCATIONS[value]?pick(LOCATIONS[value],language):String(value);return[place.city,place.countryCode?countryName(place.countryCode,language):''].filter(Boolean).join(', ')}
function fillLocationForm(prefix,value){$('#'+prefix+'-region').value=displayLocation(value)}
