const read=key=>{try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};
const locale='en';
const pick=(pair,language=locale)=>pair[language==='ko'?1:0];
function t(key,params={}){const pair=COPY[key];if(!pair)throw new Error('Missing translation: '+key);return pick(pair).replace(/\{(\w+)\}/g,(_,name)=>String(params[name]??''))}
