﻿/* MARKET DATA BOUNDARY
 * Replace window.PIECENOA_MARKET_REPOSITORY before this application starts to connect a backend.
 * Every method is asynchronous. No endpoint, database, authentication or payment service is configured here.
 * bootstrap() -> { viewer:{id}|null, profile, listings:Listing[], favorites:string[], conversations:Conversation[] }
 * uploadImage({dataUrl,name,mime}) -> {url,id?}; media URLs may be HTTP(S) or origin-relative.
 * createListing(input:ListingInput) / updateListing(id,input) -> canonical Listing
 * deleteListing(id) -> void; setFavorite(listingId,saved) -> {listingId,saved}
 * openConversation(listingId) / sendMessage(conversationId,{text,clientId}) -> canonical Conversation
 * updateProfile(profile) -> canonical profile
 * Listing: {id,ownerId,title,description,price:number,currency:'KRW',category:'painting'|'drawing'|'object'|'print',
 *   status:'available'|'reserved'|'sold',image:string,artist,medium,dimensions,year,kind,condition,delivery,framed,negotiable,
 *   location:{text:string,countryCode?:string,city?:string},region:legacy display string,
 *   createdAt:ISO string,updatedAt:ISO string,version?:string|number,seller?:{id,name,region,location,role,bio}}
 * Location text is user-entered, up to 80 characters. Optional countryCode/city from existing records remain readable.
 * Legacy Korean region-only records continue to load through normalizeLocation().
 * Conversation: {id,listingId,title,price,messages:[{id,text,createdAt,direction:'outgoing'|'incoming',state:'local'|'sent'}]}
 * Server adapters must authenticate users, authorize ownership, validate fields, store uploads and assign canonical IDs.
 * Keep access tokens and payment secrets out of this HTML. Local drafts are deliberately separate from this boundary.
 */
const CATEGORY_CODES={'회화':'painting','드로잉':'drawing','도자·오브제':'object','아트 프린트':'print'},STATUS_CODES={'판매중':'available','예약중':'reserved','판매완료':'sold'};
const categoryFromCode=code=>Object.keys(CATEGORY_CODES).find(key=>CATEGORY_CODES[key]===code)||code;
const statusFromCode=code=>Object.keys(STATUS_CODES).find(key=>STATUS_CODES[key]===code)||code;
const safeMediaURL=value=>safeImage(value)||typeof value==='string'&&(/^https?:\/\//i.test(value)||/^\/(?!\/)/.test(value));
function toListingDTO(p){const d=Number.isFinite(p.created)?p.created:Date.now();return{id:p.id,ownerId:p.ownerId||'local-user',title:p.title,description:p.description,price:p.price,currency:'KRW',category:CATEGORY_CODES[p.category]||p.category,status:STATUS_CODES[p.status]||p.status,image:p.image,artist:p.artist||'',medium:p.medium||'',dimensions:p.dimensions||'',year:p.year||'',kind:p.kind||'original',condition:p.condition||'good',delivery:p.delivery||'either',framed:p.framed||'unknown',negotiable:Boolean(p.negotiable),region:p.region,location:{text:displayLocation(p),countryCode:normalizeLocation(p).countryCode,city:normalizeLocation(p).city},createdAt:new Date(d).toISOString(),updatedAt:new Date(Number.isFinite(p.updated)?p.updated:d).toISOString(),seller:p.sellerInfo,version:p.version}}
function fromListingDTO(p,viewerId){if(!p||typeof p.id!=='string'||typeof p.title!=='string'||p.currency&&p.currency!=='KRW'||!Number.isInteger(p.price)||p.price<0||p.price>999999999||!safeMediaURL(p.image))return null;const category=categoryFromCode(p.category),status=statusFromCode(p.status);if(!categories.includes(category)||!statuses.includes(status))return null;return normalizeArtwork({...p,category,status,title:p.title.slice(0,60),description:String(p.description||'').slice(0,2000),region:String(p.region||''),created:Number.isFinite(Date.parse(p.createdAt))?Date.parse(p.createdAt):Date.now(),updated:Number.isFinite(Date.parse(p.updatedAt))?Date.parse(p.updatedAt):Date.now(),mine:Boolean(viewerId&&p.ownerId===viewerId),demo:false,sellerInfo:p.seller})}
function fromConversationDTO(c){return{id:String(c.id),listingId:String(c.listingId||c.id),title:String(c.title||''),price:Number(c.price)||0,messages:(Array.isArray(c.messages)?c.messages:[]).filter(m=>typeof m.text==='string').slice(-100).map(m=>({id:m.id,text:m.text.slice(0,500),time:m.createdAt||m.time,direction:m.direction||'outgoing',state:m.state||'local'}))}}
function createLocalMarketRepository(){
 const stored=read(storageKey)||{};let data={posts:Array.isArray(stored.posts)?stored.posts.filter(p=>p&&typeof p.id==='string'&&p.id.startsWith('local-')&&safeImage(p.image)&&Number.isInteger(p.price)&&p.price>=0&&p.price<=999999999&&categories.includes(p.category)&&statuses.includes(p.status)).map(p=>normalizeArtwork({...p,mine:true,demo:false})):[],favorites:Array.isArray(stored.favorites)?stored.favorites.filter(id=>typeof id==='string'):[],conversations:Array.isArray(stored.conversations)?stored.conversations.filter(c=>c&&typeof c.id==='string'&&Array.isArray(c.messages)).map(fromConversationDTO):[]};
 const failure=code=>Object.assign(new Error(code),{code});
 const commit=next=>{if(!write(storageKey,next))throw failure('STORAGE_FULL');data=next};
 const listingInput=input=>{const p=fromListingDTO({...input,id:input.id||'pending',ownerId:'local-user',createdAt:input.createdAt||new Date().toISOString()},'local-user');if(!p||p.title.length<2||p.description.length<10)throw failure('VALIDATION');return p};
 const conversationDTO=c=>({...c,listingId:c.listingId||c.id,messages:c.messages.map(m=>({...m,createdAt:m.createdAt||m.time,direction:m.direction||'outgoing',state:'local'}))});
 return{mode:'local-preview',
  async bootstrap(){return{viewer:{id:'local-user'},profile:read(profileKey)||{name:'',bio:'',region:'서울 성동구',role:'artist'},listings:data.posts.map(toListingDTO),favorites:[...data.favorites],conversations:data.conversations.map(conversationDTO)}},
  async uploadImage(input){if(!safeImage(input.dataUrl))throw failure('VALIDATION');return{url:input.dataUrl}},
  async createListing(input){const id='local-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),now=new Date().toISOString(),post=listingInput({...input,id,createdAt:now,updatedAt:now});commit({...data,posts:[post,...data.posts]});return toListingDTO(post)},
  async updateListing(id,input){const existing=data.posts.find(p=>p.id===id);if(!existing)throw failure('NOT_FOUND');const post=listingInput({...toListingDTO(existing),...input,id,ownerId:'local-user',createdAt:toListingDTO(existing).createdAt,updatedAt:new Date().toISOString()});commit({...data,posts:data.posts.map(p=>p.id===id?post:p)});return toListingDTO(post)},
  async deleteListing(id){if(!data.posts.some(p=>p.id===id))throw failure('NOT_FOUND');commit({...data,posts:data.posts.filter(p=>p.id!==id),favorites:data.favorites.filter(key=>key!==id)})},
  async setFavorite(listingId,saved){const next=new Set(data.favorites);saved?next.add(listingId):next.delete(listingId);commit({...data,favorites:[...next]});return{listingId,saved}},
  async openConversation(listingId){let thread=data.conversations.find(c=>(c.listingId||c.id)===listingId);if(thread)return conversationDTO(thread);const post=findPost(listingId);if(!post)throw failure('NOT_FOUND');thread={id:'thread-'+listingId,listingId,title:workText(post,'title'),price:post.price,messages:[]};commit({...data,conversations:[thread,...data.conversations]});return conversationDTO(thread)},
  async sendMessage(id,input){const existing=data.conversations.find(c=>c.id===id);if(!existing)throw failure('NOT_FOUND');if(existing.messages.length>=100||!input.text.trim()||input.text.length>500)throw failure('VALIDATION');if(existing.messages.some(m=>m.id===input.clientId))return conversationDTO(existing);const message={id:input.clientId,text:input.text.trim(),time:new Date().toISOString(),direction:'outgoing',state:'local'},thread={...existing,messages:[...existing.messages,message]};commit({...data,conversations:data.conversations.map(c=>c.id===id?thread:c)});return conversationDTO(thread)},
  async updateProfile(value){if(!write(profileKey,value))throw failure('STORAGE_FULL');return{...value}}
 };
}
const repository=window.PIECENOA_MARKET_REPOSITORY||createLocalMarketRepository(),isPreview=repository.mode==='local-preview';
let repositoryReady=false,viewerId=null,marketLoading=true,marketLoadFailed=false;const pendingFavorites=new Set();let publishing=false,sendingMessage=false;
function repositoryError(error){const code=error?.code;notify(code==='STORAGE_FULL'?'error_storage':code==='AUTH_REQUIRED'?'auth_required':code==='CONFLICT'?'market_conflict':'market_action_error')}
function requireMarketReady(){if(repositoryReady){if(!isPreview&&!viewerId){notify('auth_required');return false}return true;}notify('market_loading');return false}
function mergeListing(dto){const p=fromListingDTO(dto,viewerId);if(!p)throw Object.assign(new Error('Invalid listing response'),{code:'VALIDATION'});posts=posts.some(item=>item.id===p.id)?posts.map(item=>item.id===p.id?p:item):[p,...posts];return p}
