function renderMarketDataState(){const banner=$('#market-data-state');if(!banner)return;banner.hidden=!marketLoading&&!marketLoadFailed;$('#market-data-text').textContent=t(marketLoadFailed?'market_load_error':'market_loading');$('#retry-market-data').hidden=!marketLoadFailed}
async function initializeMarketData(){marketLoading=true;marketLoadFailed=false;renderMarketDataState();try{for(const method of ['bootstrap','uploadImage','createListing','updateListing','deleteListing','setFavorite','openConversation','sendMessage','updateProfile'])if(typeof repository[method]!=='function')throw Error('Missing repository method');const data=await repository.bootstrap();viewerId=typeof data.viewer?.id==='string'?data.viewer.id:null;posts=(Array.isArray(data.listings)?data.listings:[]).map(p=>fromListingDTO(p,viewerId)).filter(Boolean);favorites=new Set(Array.isArray(data.favorites)?data.favorites:[]);conversations=(Array.isArray(data.conversations)?data.conversations:[]).map(fromConversationDTO);const value=data.profile||{};profile={name:String(value.name||'').slice(0,40),bio:String(value.bio||'').slice(0,240),...normalizeLocation(value),role:['artist','collector','studio'].includes(value.role)?value.role:'artist'};repositoryReady=true}catch{marketLoadFailed=true;repositoryReady=false}finally{marketLoading=false;renderMarketDataState();if(document.body.dataset.view==='market')render()}}

